"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["83047"],{34575(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.etapa_texto_tamanho","status":422,"titulo":"A descri\xe7\xe3o ou o aviso da etapa excede o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.estrutura_formulario.etapa_texto_tamanho","requisitos":[],"oQueAconteceu":["A `descricao` ou o `aviso` de uma etapa do formul\xe1rio tem mais de 2000 caracteres depois de aparado. Os dois textos s\xe3o opcionais: a descri\xe7\xe3o apresenta a etapa ao candidato, e o aviso destaca o que ele precisa saber antes de responder. A mensagem diz qual dos dois excedeu: \\"A descri\xe7\xe3o da etapa tem no m\xe1ximo 2000 caracteres.\\" ou \\"O aviso da etapa tem no m\xe1ximo 2000 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `etapas[i].descricao` ou `etapas[i].aviso`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. Cada texto recusado tem a pr\xf3pria entrada, no mesmo lote das demais recusas da forma da etapa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Encurte o texto para at\xe9 2000 caracteres, ou retire-o: a etapa funciona sem descri\xe7\xe3o e sem aviso."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);